output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_corridor",
    "text": "A shopper must not push or hold a cart inside a single-file shelf corridor.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCorridor": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfCorridor"
        ]
      }
    },
    "justification": "The rule refers to the layout-independent relation of being in a narrow corridor flanked by shelves, not to any particular aisle coordinates."
  },
  {
    "id": "no_cart_entry_to_single_file_shelf_corridor",
    "text": "A shopper must not move a cart into a single-file shelf corridor.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCorridor": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileShelfCorridorWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "singleFileShelfCorridor"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileShelfCorridorWithCart"
    },
    "justification": "The norm is about the general act of entering an aisle too narrow for carts, defined by shelf adjacency and available width rather than by named cells."
  },
  {
    "id": "collect_single_file_shelf_items_on_foot",
    "text": "Items reached from a single-file shelf corridor must be interacted with without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCorridor": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "shelfInteraction": {
          "and": [
            "INTERACT",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelfInteraction",
          "singleFileShelfCorridor",
          "hasCart"
        ]
      }
    },
    "justification": "The rule distinguishes shelf access in constrained aisles from shelf access in open aisles using geometry, so it transfers to any store with narrow shelf corridors."
  },
  {
    "id": "park_cart_only_in_spacious_open_aisle",
    "text": "When setting down a cart, the shopper must park it in a spacious open aisle rather than beside shelves or in a constricted passage.",
    "abstraction": {
      "state_properties": {
        "spaciousOpenAisle": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "gt": [
                "freeWidthH",
                2
              ]
            },
            {
              "gt": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {
        "putDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "putDownCart",
          {
            "not": "spaciousOpenAisle"
          }
        ]
      }
    },
    "justification": "The parking location is characterized by openness and clearance, which are meaningful in any floor plan and do not name the demonstrated cart-drop cells."
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart, the shopper is obliged to retrieve a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "putDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "putDownCart",
      "discharge": "takeCart"
    },
    "justification": "The norm concerns the general lifecycle of temporarily leaving and reclaiming a cart, independent of where in the store that occurs."
  },
  {
    "id": "leave_store_with_cart",
    "text": "A shopper who exits the store must not leave without the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "Exiting while still responsible for a cart is a domain-level behaviour constraint and does not depend on the exit cell's coordinates."
  },
  {
    "id": "obtain_cart_for_shopping_trip",
    "text": "At the start of a shopping trip, the shopper is obliged to obtain a cart.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCart"
    },
    "justification": "The rule is about standard shopping conduct at trip start and refers only to acquiring a cart, not to a particular cart-station coordinate."
  },
  {
    "id": "return_to_cart_after_single_file_access",
    "text": "After entering a single-file shelf corridor on foot, the shopper is obliged to return to a cart before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCorridor": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "onFootInSingleFileShelfCorridor": {
          "and": [
            {
              "not": "hasCart"
            },
            "singleFileShelfCorridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootInSingleFileShelfCorridor",
      "discharge": "hasCart"
    },
    "justification": "The trigger is defined by being temporarily separated from the cart in a narrow shelf corridor, a relation that generalizes across store layouts."
  }
]
